import{_ as e,c as r,o as i,ah as n}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"18、【蠱】 巽下艮上","description":"溫公易說 - 18、【蠱】 巽下艮上","frontmatter":{"title":"18、【蠱】 巽下艮上","description":"溫公易說 - 18、【蠱】 巽下艮上"},"headers":[],"relativePath":"classics/wengong/019.md","filePath":"classics/wengong/019.md"}'),l={name:"classics/wengong/019.md"};function t(h,a,s,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[n('<h1 id="_18、【蠱】-巽下艮上" tabindex="-1">18、【蠱】 巽下艮上 <a class="header-anchor" href="#_18、【蠱】-巽下艮上" aria-label="Permalink to “18、【蠱】 巽下艮上”">​</a></h1><h3 id="彖曰-蠱-剛上而柔下-巽而止-蠱。蠱元亨而天下治也。利涉大川-往有事也。先甲三日-後甲三日-終則有始-天行也。" tabindex="-1">彖曰：蠱，剛上而柔下，巽而止，蠱。蠱元亨而天下治也。利涉大川，往有事也。先甲三日，後甲三日，終則有始，天行也。 <a class="header-anchor" href="#彖曰-蠱-剛上而柔下-巽而止-蠱。蠱元亨而天下治也。利涉大川-往有事也。先甲三日-後甲三日-終則有始-天行也。" aria-label="Permalink to “彖曰：蠱，剛上而柔下，巽而止，蠱。蠱元亨而天下治也。利涉大川，往有事也。先甲三日，後甲三日，終則有始，天行也。”">​</a></h3><p>蠱者，物有蠹敝而事之也。事之者，治之也。除蠹補敝，故大通也。剛上而柔下，善登而惡降也。巽而止之，利以濟難也。甲者，生之始，為仁為德。庚者，殺之終，為義為刑。先之三日以謹其始，後之三日以慎其終。蠱以少陽在上而行令，故主仁。巽以少陰在上而行令，故主義。天以陰陽終始，萬物君子以仁義修身，以德刑治國，各有其事也。</p><h3 id="象曰-山下有風-蠱。君子以振民育德。" tabindex="-1">象曰：山下有風，蠱。君子以振民育德。 <a class="header-anchor" href="#象曰-山下有風-蠱。君子以振民育德。" aria-label="Permalink to “象曰：山下有風，蠱。君子以振民育德。”">​</a></h3><p>艮為丘為山，巽為風為號令。君子洗濯其心，一以待人，以育德於上。山之象也，發號施令，革弊除蠹，以振民於下。風之象也。</p><h3 id="初六-幹父之蠱-有子考無咎-厲終吉-象曰-幹父之蠱-意承考也。" tabindex="-1">初六：幹父之蠱，有子考無咎，厲終吉 象曰：幹父之蠱，意承考也。 <a class="header-anchor" href="#初六-幹父之蠱-有子考無咎-厲終吉-象曰-幹父之蠱-意承考也。" aria-label="Permalink to “初六：幹父之蠱，有子考無咎，厲終吉 象曰：幹父之蠱，意承考也。”">​</a></h3><p>子者所以承父之事而成之，臣者所以成君之事而終之。天下之事大矣，多矣，自非聖人不能無過。故子能葢父之愆，臣能掩君之惡，然後為幹蠱也。以秦始漢武之奢汰驕暴，相逺也無幾耳。始皇得胡亥以為子，李斯以為臣，不旋踵而亡矣。天下後世之言惡者必歸焉。武帝得昭帝以為子，霍光以為臣，而國家乂寧，後世稱之為明君。隋唐之祖亦然，故必有賢子然後考得無咎也。幹事之始，敢自安乎？故戰戰兢兢，乃得終吉也。夫事有蠱敝，不可不更。臣子之心非以高君父而自名也，欲以掩惡而全美，故曰意承考也。</p><h3 id="九二-幹母之蠱-不可貞-象曰-幹母之蠱-得中道也。" tabindex="-1">九二：幹母之蠱，不可貞 象曰：幹母之蠱，得中道也。 <a class="header-anchor" href="#九二-幹母之蠱-不可貞-象曰-幹母之蠱-得中道也。" aria-label="Permalink to “九二：幹母之蠱，不可貞 象曰：幹母之蠱，得中道也。”">​</a></h3><h3 id="九三-幹父之蠱-小有悔-無大咎-象曰-幹父之蠱-終無咎也。" tabindex="-1">九三：幹父之蠱，小有悔，無大咎 象曰：幹父之蠱，終無咎也。 <a class="header-anchor" href="#九三-幹父之蠱-小有悔-無大咎-象曰-幹父之蠱-終無咎也。" aria-label="Permalink to “九三：幹父之蠱，小有悔，無大咎 象曰：幹父之蠱，終無咎也。”">​</a></h3><p>親有過，下氣怡聲以諫，禮也。三以重剛乾之故，小有悔也。然不失其正，故無大咎也。</p><h3 id="六四-裕父之蠱-往見吝-象曰-裕父之蠱-往未得也。" tabindex="-1">六四：裕父之蠱，往見吝 象曰：裕父之蠱，往未得也。 <a class="header-anchor" href="#六四-裕父之蠱-往見吝-象曰-裕父之蠱-往未得也。" aria-label="Permalink to “六四：裕父之蠱，往見吝 象曰：裕父之蠱，往未得也。”">​</a></h3><p>六四裕父之蠱，楚屈到嗜芰，有疾，屬之曰祭我必以芰。及祥，宗老將薦芰，屈建命去之曰：國君有牛享，大夫有羊饋，士有豚豕之奠，庶人有魚炙之薦，不羞珍異，不陳庶侈。夫子不以其私慾幹國之典，遂不用。易曰：裕父之蠱，往見吝。裕之為言饒也，益也。父不義而順之，是裕之也。往而不變，斯可醜也。</p><h3 id="六五-幹父之蠱-用譽-象曰-幹父用譽-承以德也。" tabindex="-1">六五：幹父之蠱，用譽 象曰：幹父用譽，承以德也。 <a class="header-anchor" href="#六五-幹父之蠱-用譽-象曰-幹父用譽-承以德也。" aria-label="Permalink to “六五：幹父之蠱，用譽 象曰：幹父用譽，承以德也。”">​</a></h3><p>五居盛位，以柔承剛，又有中和之德，故有譽也。</p><h3 id="上九-不事王侯-高尚其志-象曰-不事王侯-志可則也。" tabindex="-1">上九：不事王侯，高尚其志 象曰：不事王侯，志可則也。 <a class="header-anchor" href="#上九-不事王侯-高尚其志-象曰-不事王侯-志可則也。" aria-label="Permalink to “上九：不事王侯，高尚其志 象曰：不事王侯，志可則也。”">​</a></h3><p>陽者君子之象，致仕而無位，年高而德尊。雖不能以力幹事，而智慮深逺，志可法也。故先王養老乞言焉，非夫矯亢以驚俗，虛驕而無用者也。</p>',16)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
